begin
  update public.section_templates
  set default_content = default_content || patch
  where type = 'diocese_map_section'::public.section_type;

  update public.sections s
  set content = coalesce(s.content, '{}'::jsonb) || patch,
      updated_at = now()
  from public.pages p
  where s.page_id = p.id
    and p.slug = 'about'
    and s.section_key = 'about_network'
    and s.type = 'diocese_map_section'::public.section_type;
end $$;
